import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { parse } from "yaml";
import { z } from "zod";
import { Charter } from "./schemas.js";

export class CharterError extends Error {}

/** Parse one charter file. Every problem is reported with its key path, so the PR author can fix it. */
export function parseCharter(file: string, text: string): Charter {
  const result = Charter.safeParse(parse(text));
  if (!result.success) throw new CharterError(`${file}:\n${z.prettifyError(result.error)}`);
  if (result.data.name !== file.replace(/\.yaml$/, "")) throw new CharterError(`${file}: name must match the file name`);
  return result.data;
}

/** Load every charter in a folder. In the orchestrator this runs in the loadCharter activity, pinned to a commit. */
export async function loadCharters(dir: string): Promise<Map<string, Charter>> {
  const charters = new Map<string, Charter>();
  for (const file of (await readdir(dir)).filter((f) => f.endsWith(".yaml")).sort()) {
    charters.set(file.replace(/\.yaml$/, ""), parseCharter(file, await readFile(join(dir, file), "utf8")));
  }
  return charters;
}

