import { matchesGlob, relative, resolve } from "node:path";
import type { HookCallback } from "@anthropic-ai/claude-agent-sdk/core";
import type { Charter } from "@rhinohealth/ai-agents-shared";

const REPO = "/work/fcp";  // the checkout; a routine on another repo uses its own folder
const inside = (rel: string, globs: string[]) => globs.some((g) => matchesGlob(rel, g));

/** The same rule the broker's git proxy applies again at push, to every changed path. */
export function pathAllowed(rel: string, c: Charter): boolean {
  return inside(rel, c.allowed_paths) && !inside(rel, c.denied_paths);
}

export const charterPaths = (c: Charter): HookCallback => async (input) => {  // PreToolUse, matcher "Edit|Write"
  if (input.hook_event_name !== "PreToolUse") return {};
  const path = (input.tool_input as { file_path?: string }).file_path;
  if (!path) return {};
  const rel = relative(REPO, resolve(path));
  if (pathAllowed(rel, c)) return {};
  return { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny",
    permissionDecisionReason: `${rel} is outside the ${c.name} charter. Leave it, and list it in the PR for a person.` } };
};

