import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { loadCharters, parseCharter, CharterError } from "../src/charter.js";

const fe = readFileSync(new URL("../charters/fe-ci-fixer.yaml", import.meta.url), "utf8");

test("every charter in charters/ loads", async () => {
  const charters = await loadCharters(new URL("../charters/", import.meta.url).pathname);
  assert.ok(charters.size >= 1);
  assert.equal(charters.get("fe-ci-fixer")?.repo, "RhinoHealth/fcp");  // the default fills in
});

test("an unknown key is rejected", () => {
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", fe + "max_turns: 50\n"), CharterError);
});

test("an empty allowed_paths is rejected", () => {
  const empty = fe.replace('allowed_paths: ["frontend/**"]', "allowed_paths: []");
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", empty), /allowed_paths/);
});
